<?php
namespace Database\Seeders;use App\Models\Vehicle;use App\Models\VehicleCategory;use App\Models\VehicleFeature;use Illuminate\Database\Seeder;
class VehicleSeeder extends Seeder{public function run():void{$c=VehicleCategory::firstOrCreate(['slug'=>'mpv'],['name'=>'MPV']);$features=collect(['AC','Bluetooth','USB Charger','Kamera Parkir'])->map(fn($n)=>VehicleFeature::firstOrCreate(['name'=>$n]));foreach([['code'=>'AVZ-001','brand'=>'Toyota','model'=>'Avanza','plate'=>'B 1234 RNT','price'=>500000],['code'=>'INN-001','brand'=>'Toyota','model'=>'Innova','plate'=>'B 5678 RNT','price'=>750000],['code'=>'BRV-001','brand'=>'Honda','model'=>'BR-V','plate'=>'B 9012 RNT','price'=>600000]] as $x){$v=Vehicle::updateOrCreate(['code'=>$x['code']],['vehicle_category_id'=>$c->id,'brand'=>$x['brand'],'model'=>$x['model'],'year'=>2025,'license_plate'=>$x['plate'],'color'=>'Putih','transmission'=>'AUTOMATIC','fuel_type'=>'GASOLINE','seat_capacity'=>7,'daily_price'=>$x['price'],'driver_daily_price'=>200000,'security_deposit'=>500000,'current_odometer'=>12000,'status'=>'AVAILABLE','featured'=>true]);$v->features()->sync($features->pluck('id'));$v->images()->firstOrCreate(['file_path'=>'vehicles/test-mpv.png'],['is_primary'=>true]);}}}
